    return version if isinstance(version, Version) else parse(version)


def _cmp(a, b) -> int:
    return (a > b) - (a < b)


def _compare_prerelease(a: tuple[str, ...], b: tuple[str, ...]) -> int:
    if not a or not b:
        # No pre-release ranks above any pre-release.
        return _cmp(not a, not b)
    for x, y in zip(a, b):
