from __future__ import annotations

import re
from datetime import datetime, timedelta

_MONTHS = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN",
           "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"]  # fmt: skip
_DAYS = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"]

# (low, high, names) for minute, hour, day of month, month, day of week.
_FIELDS = [
    (0, 59, {}),
    (0, 23, {}),
    (1, 31, {}),
    (1, 12, {name: i + 1 for i, name in enumerate(_MONTHS)}),
    (0, 7, {name: i for i, name in enumerate(_DAYS)}),
]

_ITEM_RE = re.compile(r"(\*|(\w+)(?:-(\w+))?)(?:/([0-9]+))?")


def _value(text: str, low: int, high: int, names: dict[str, int]) -> int:
    if text.upper() in names:
        return names[text.upper()]
    if not re.fullmatch(r"[0-9]+", text):
        raise ValueError(f"invalid value: {text!r}")
    value = int(text)
    if not low <= value <= high:
        raise ValueError(f"value out of range: {text!r}")
    return value


def _parse_field(text: str, low: int, high: int, names: dict[str, int]) -> set[int]:
    values = set()
    for item in text.split(","):
        match = _ITEM_RE.fullmatch(item)
        if not match:
            raise ValueError(f"invalid item: {item!r}")
        whole, first, last, step = match.groups()
