from __future__ import annotations

import calendar
import re
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from decimal import Decimal

_DURATION_RE = re.compile(
    r"P(?:([0-9]+)Y)?(?:([0-9]+)M)?(?:([0-9]+)W)?(?:([0-9]+)D)?"
    r"(T(?:([0-9]+)H)?(?:([0-9]+)M)?(?:([0-9]+(?:\.[0-9]+)?)S)?)?"
)


@dataclass(frozen=True)
class Duration:
    years: int = 0
    months: int = 0
    weeks: int = 0
    days: int = 0
    hours: int = 0
    minutes: int = 0
    seconds: float = 0


def parse(text: str) -> Duration:
    """Parse an ISO 8601 duration."""
    match = _DURATION_RE.fullmatch(text)
    if not match:
        raise ValueError(f"invalid duration: {text!r}")
    years, months, weeks, days, time, hours, minutes, seconds = match.groups()
    date_parts = (years, months, weeks, days)
    time_parts = (hours, minutes, seconds)
    if time is not None and all(part is None for part in time_parts):
        raise ValueError(f"invalid duration: {text!r}")
    if all(part is None for part in date_parts + time_parts):
        raise ValueError(f"invalid duration: {text!r}")
    if seconds is None:
        seconds = 0
    elif "." in seconds:
        seconds = float(seconds)
    else:
        seconds = int(seconds)
    return Duration(
        *(int(part or 0) for part in date_parts + (hours, minutes)), seconds
    )


def _format_seconds(seconds: float) -> str:
    if float(seconds).is_integer():
        return str(int(seconds))
    # Via repr to get the shortest digits, and Decimal to avoid exponents.
    return f"{Decimal(repr(float(seconds))):f}"


def format(duration: Duration) -> str:
    """Write ``duration`` in canonical ISO 8601 form."""
    d = duration
    fields = (d.years, d.months, d.weeks, d.days, d.hours, d.minutes, d.seconds)
    if any(value < 0 for value in fields):
        raise ValueError(f"negative duration: {duration!r}")
    date = "".join(
        f"{value}{unit}"
        for value, unit in zip((d.years, d.months, d.weeks, d.days), "YMWD")
        if value
    )
    time = "".join(
        f"{value}{unit}" for value, unit in zip((d.hours, d.minutes), "HM") if value
    )
    if d.seconds:
        time += _format_seconds(d.seconds) + "S"
    if not date and not time:
        return "PT0S"
    return "P" + date + ("T" + time if time else "")


def add(moment: datetime, duration: Duration) -> datetime:
    """``moment`` plus ``duration``."""
    month_index = moment.month - 1 + duration.years * 12 + duration.months
    year, month = moment.year + month_index // 12, month_index % 12 + 1
    day = min(moment.day, calendar.monthrange(year, month)[1])
    moment = moment.replace(year=year, month=month, day=day)

    elapsed = timedelta(
        weeks=duration.weeks,
        days=duration.days,
        hours=duration.hours,
        minutes=duration.minutes,
        seconds=duration.seconds,
    )
    if moment.tzinfo is None:
        return moment + elapsed
    # Aware datetimes add wall-clock time; go through UTC for elapsed time.
    return (moment.astimezone(timezone.utc) + elapsed).astimezone(moment.tzinfo)

