from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = re.compile(r"(:?)-+(:?)")


def _cell_text(value) -> str:
    return "" if value is None else str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    space = width - len(text)
    if alignment == "right":
        return " " * space + text
    if alignment == "center":
        return " " * (space // 2) + text + " " * (space - space // 2)
    return text + " " * space


def _delimiter(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


